head.script:
// 테스트 설명, 유효성 값 설정
//  - column 샘플 관례 : textAlign 은 Body Column 에만 설정 (설정 영역 con 옵션 미생성)
//    "전체 영역의 Column 에서 동작합니다." 는 inputType 이 다른 Body Column(text, select, checkbox, calendar, textImage, drilldown) 을 con_targetColumn 으로 골라 확인
//  - 본 샘플(_1) : left / center / right / 미설정 정렬 축
//  - CSS 클래스, setColumnStyle() / setCellStyle() 과의 우선순위는 column_P_textAlign_2 소유
//  - 편집 상태 입력창 정렬은 column_P_textAlign_3 소유
scwin.tData = {
    "description" : "[column > P > textAlign]<br/>Column 에 표시되는 텍스트의 가로 정렬 방법을 설정합니다.",
    "validation" : [
        "전체 영역의 Column 에서 동작합니다.",
        "left 설정 시, 텍스트를 왼쪽으로 정렬합니다.",
        "center 설정 시, 텍스트를 가운데로 정렬합니다.",
        "미설정 시, 텍스트를 가운데로 정렬합니다.",
        "right 설정 시, 텍스트를 오른쪽으로 정렬합니다."
    ]
}



// Body Column 정보 (Body Column 인덱스 순)
scwin.bodyInfo = [
    { "id" : "name",   "label" : "이름(text)" },
    { "id" : "dept",   "label" : "부서(select)" },
    { "id" : "chk",    "label" : "확인(checkbox)" },
    { "id" : "inDate", "label" : "입사일(calendar)" },
    { "id" : "city",   "label" : "지역(textImage)" },
    { "id" : "org",    "label" : "조직(drilldown)" }
];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_textAlign.setValue("right");
    con_targetColumn.setValue("name");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - textAlign(con 값) 은 con_targetColumn 에서 고른 Body Column 1개에만 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }

    let cTextAlign = con_textAlign.getValue();
    let cTarget = con_targetColumn.getValue();

    let strNameSpace = $c.gcm.getNameSpace();

    // 바인딩 dataList (depth : drilldown 계층 깊이)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="inDate" name="inDate" dataType="date"></w2:column>';
    strDlt += '<w2:column id="city" name="city" dataType="text"></w2:column>';
    strDlt += '<w2:column id="org" name="org" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "dept" : "01", "chk" : "1", "inDate" : "20261001", "city" : "서울", "org" : "영업본부", "depth" : "1" },
        { "name" : "김영희", "dept" : "02", "chk" : "0", "inDate" : "20261005", "city" : "부산", "org" : "영업1팀", "depth" : "2" },
        { "name" : "이철수", "dept" : "01", "chk" : "1", "inDate" : "20261012", "city" : "대구", "org" : "개발본부", "depth" : "1" },
        { "name" : "박민수", "dept" : "02", "chk" : "0", "inDate" : "20261020", "city" : "광주", "org" : "개발1팀", "depth" : "2" }
    ], false);

    // 검증 대상 Body Column 속성
    let attr = function (id) {
        return (cTarget === id && cTextAlign !== '') ? ' textAlign="' + cTextAlign + '"' : '';
    };

    let strItem = '<w2:choices>'
                + '<w2:item><w2:label>영업</w2:label><w2:value>01</w2:value></w2:item>'
                + '<w2:item><w2:label>개발</w2:label><w2:value>02</w2:value></w2:item>'
                + '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:900px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    for (let i = 0; i < scwin.bodyInfo.length; i++) {
        strTarget += '<w2:column width="150" style="" inputType="text" id="h_' + scwin.bodyInfo[i].id + '" value="' + scwin.bodyInfo[i].label + '"></w2:column>';
    }
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" id="name" inputType="text"' + attr("name") + '></w2:column>';
    strTarget += '<w2:column width="150" style="" id="dept" inputType="select"' + attr("dept") + '>' + strItem + '</w2:column>';
    strTarget += '<w2:column width="150" style="" id="chk" inputType="checkbox" trueValue="1" falseValue="0" valueType="other"' + attr("chk") + '></w2:column>';
    strTarget += '<w2:column width="150" style="" id="inDate" inputType="calendar" dataType="date" displayFormat="yyyy-MM-dd"' + attr("inDate") + '></w2:column>';
    strTarget += '<w2:column width="150" style="" id="city" inputType="textImage"' + attr("city") + '></w2:column>';
    strTarget += '<w2:column width="150" style="" id="org" inputType="drilldown" depthColumn="depth" showDepth="2"' + attr("org") + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 대상 Body Column 의 Row 별 정렬 상태 출력
//  - validation 1 : con_targetColumn 별(inputType 무관) 결과로 판정
//  - validation 2 ~ 5 : td style text-align / 계산된 text-align / 내용의 좌우 여백(px)
scwin.btn_checkAlign_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let cTextAlign = con_textAlign.getValue();
    let cTarget = con_targetColumn.getValue();
    let colIndex = -1;
    for (let i = 0; i < scwin.bodyInfo.length; i++) {
        if (scwin.bodyInfo[i].id === cTarget) {
            colIndex = i;
        }
    }
    bottom.setReturnValue("textAlign : " + (cTextAlign === '' ? "(미설정)" : cTextAlign) + " / 대상 Column : " + scwin.bodyInfo[colIndex].label);

    for (let r = 0; r < target1.getRowCount(); r++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + r + "_" + colIndex + "']");
        if (!td) {
            continue;
        }
        // 내용 영역(텍스트, 체크박스 등) 과 td 의 좌우 간격
        let tdRect = td.getBoundingClientRect();
        let range = document.createRange();
        range.selectNodeContents(td);
        let cRect = range.getBoundingClientRect();
        let gapL = Math.round(cRect.left - tdRect.left);
        let gapR = Math.round(tdRect.right - cRect.right);
        bottom.setReturnValue("Row " + r + " : td style text-align = " + (td.style.textAlign || "(없음)") + ", 계산된 text-align = " + getComputedStyle(td).textAlign + ", 좌우 여백 = " + gapL + "px / " + gapR + "px");
    }
}
